int sumOfMax(int arr[], int n) {
    int res = 0;

    // Pick starting point of subarray
    for (int i = 0; i < n; ++i) {
        int currMax = arr[i];

        // Pick ending point
        for (int j = i; j < n; ++j) {

            // Max of subarray from i to j
            if (arr[j] > currMax) {
                currMax = arr[j];
            }

            res += currMax;
        }
    }

    return res;
}

int main() {
    int arr[] = {1, 3, 2};
    int n = sizeof(arr) / sizeof(arr[0]);

    printf("%d\n", sumOfMax(arr, n));

    return 0;
}


